class Solution {
    public int islandPerimeter(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int perimeter = 0;
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (grid[row][col] == 0) {
                    continue;
                }
                for (int[] direction : directions) {
                    int nextRow = row + direction[0];
                    int nextCol = col + direction[1];
                    if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols
                            || grid[nextRow][nextCol] == 0) {
                        perimeter++;
                    }
                }
            }
        }
        return perimeter;
    }
}

class Solution {
    public int islandPerimeter(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int land = 0;
        int shared = 0;

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (grid[row][col] == 0) {
                    continue;
                }
                land++;
                if (row + 1 < rows && grid[row + 1][col] == 1) {
                    shared++;
                }
                if (col + 1 < cols && grid[row][col + 1] == 1) {
                    shared++;
                }
            }
        }

        return land * 4 - shared * 2;
    }
}

class Solution {
    public int islandPerimeter(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (grid[row][col] == 1) {
                    return dfs(grid, visited, row, col);
                }
            }
        }
        return 0;
    }

    private int dfs(int[][] grid, boolean[][] visited, int row, int col) {
        int rows = grid.length;
        int cols = grid[0].length;
        if (row < 0 || row >= rows || col < 0 || col >= cols || grid[row][col] == 0) {
            return 1;
        }
        if (visited[row][col]) {
            return 0;
        }
        visited[row][col] = true;
        return dfs(grid, visited, row + 1, col)
                + dfs(grid, visited, row - 1, col)
                + dfs(grid, visited, row, col + 1)
                + dfs(grid, visited, row, col - 1);
    }
}

class Solution {
    public int islandPerimeter(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] seen = new boolean[rows][cols];
        java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();

        for (int row = 0; row < rows && queue.isEmpty(); row++) {
            for (int col = 0; col < cols; col++) {
                if (grid[row][col] == 1) {
                    queue.add(new int[] {row, col});
                    seen[row][col] = true;
                    break;
                }
            }
        }

        int perimeter = 0;
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!queue.isEmpty()) {
            int[] cell = queue.remove();
            for (int[] direction : directions) {
                int nextRow = cell[0] + direction[0];
                int nextCol = cell[1] + direction[1];
                if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols
                        || grid[nextRow][nextCol] == 0) {
                    perimeter++;
                } else if (!seen[nextRow][nextCol]) {
                    seen[nextRow][nextCol] = true;
                    queue.add(new int[] {nextRow, nextCol});
                }
            }
        }
        return perimeter;
    }
}
